style.css:
@-moz-document domain("discord.com") {
/* Targets Discord's root color variables */
  html, [class*="theme-"] {
    --background-primary: #fff0f5 !important;    /* Soft lavender pink chat */
    --background-secondary: #ffe4e1 !important;  /* Misty rose sidebars */
    --background-tertiary: #ffd1dc !important;   /* Pastel pink server list */
    --background-accent: #ff69b4 !important;     /* Hot pink accents */
    
    --channel-textarea-background: #ffffff !important; /* White text box */
    --text-normal: #FF8FCD !important;           /* Deep berry text for readability */
    --text-muted: #8b5a6c !important;            /* Muted text color */
    
    --brand-experiment: #ff69b4 !important;      /* Changes mention highlights to pink */
    --brand-experiment-500: #ff69b4 !important;  /* Changes main buttons to pink */
  }

  /* Ensures scrollbars match the pink aesthetic */
  [class*="scrollbar-"] {
    background-color: #ffe4e1 !important;
  }
}
